from PIL import Image, ImageChops, ImageOps
from collections import deque

def components(mask, min_size=50):
    w,h=mask.size
    visited=set(); comps=[]
    for y in range(h):
        for x in range(w):
            if mask.getpixel((x,y)) and (x,y) not in visited:
                q=deque([(x,y)]); visited.add((x,y)); xs=[]; ys=[]; n=0
                while q:
                    cx,cy=q.popleft(); n+=1; xs.append(cx); ys.append(cy)
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=cx+dx,cy+dy
                        if 0<=nx<w and 0<=ny<h and mask.getpixel((nx,ny)) and (nx,ny) not in visited:
                            visited.add((nx,ny)); q.append((nx,ny))
                if n>=min_size:
                    comps.append((n,(min(xs),min(ys),max(xs)+1,max(ys)+1),(sum(xs)//n,sum(ys)//n)))
    comps.sort(reverse=True)
    return comps

for base_name, cur_name, label in [('door_001.jpg','door_006.jpg','door'),('overview_002.jpg','overview_007.jpg','overview')]:
    base=Image.open('/home/robot/captures/'+base_name).convert('RGB')
    cur=Image.open('/home/robot/captures/'+cur_name).convert('RGB')
    diff=ImageChops.difference(base,cur)
    gray=ImageOps.grayscale(diff)
    for thresh in [20,40,60,80]:
        mask=gray.point(lambda p: 255 if p>thresh else 0)
        comps=components(mask)
        print(label,'thresh',thresh,'num',len(comps))
        for c in comps[:10]:
            print(' ',c)
